package databaseuser_test

import (
	"context"
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/terraform"
	"github.com/mongodb/terraform-provider-mongodbatlas/internal/common/conversion"
	"github.com/mongodb/terraform-provider-mongodbatlas/internal/testutil/acc"
	"github.com/mongodb/terraform-provider-mongodbatlas/internal/testutil/mig"
)

// Migration tests for the autogenerated mongodbatlas_database_user live here (the
// autogen package owns them permanently); see the autogen transition spike doc.

const (
	resourceName = "mongodbatlas_database_user.test"
)

func TestMigDatabaseUser_basic(t *testing.T) {
	var (
		projectID = acc.ProjectIDExecution(t)
		username  = acc.RandomName()
		// Step 1 config: nested collections as blocks, the syntax the manual (released)
		// implementation requires.
		config = acc.ConfigDatabaseUserBasic(projectID, username, "atlasAdmin", "First Key", "First value")
		// Step 2+ configs: nested collections as assignments instead of blocks, the syntax
		// the autogen implementation requires (accepted breaking change: customers rewrite
		// their configs; values stay the same).
		configTPF = acc.ConfigDatabaseUserBasicTPF(projectID, username, "atlasAdmin", "First Key", "First value")
	)

	resource.ParallelTest(t, resource.TestCase{
		PreCheck:     func() { mig.PreCheckBasic(t) },
		CheckDestroy: checkDestroy,
		Steps: []resource.TestStep{
			{
				ExternalProviders: mig.ExternalProviders(),
				Config:            config,
				Check: resource.ComposeAggregateTestCheckFunc(
					resource.TestCheckResourceAttr(resourceName, "project_id", projectID),
					resource.TestCheckResourceAttr(resourceName, "username", username),
					resource.TestCheckResourceAttr(resourceName, "password", "test-acc-password"),
					resource.TestCheckResourceAttr(resourceName, "auth_database_name", "admin"),
					resource.TestCheckResourceAttr(resourceName, "labels.#", "1"),
					resource.TestCheckResourceAttr(resourceName, "roles.#", "1"),
				),
			},
			{
				// Accepts the known one-time migration diff (e.g. optional strings the API
				// returns as "" while the manual resource kept null).
				Config:                   configTPF,
				ProtoV6ProviderFactories: acc.TestAccProviderV6Factories,
				PlanOnly:                 true,
				ExpectNonEmptyPlan:       true,
			},
			{
				// Applies the rewritten config and asserts identity survived (no replacement).
				Config:                   configTPF,
				ProtoV6ProviderFactories: acc.TestAccProviderV6Factories,
				Check: resource.ComposeAggregateTestCheckFunc(
					checkExists(resourceName),
					resource.TestCheckResourceAttr(resourceName, "id", encodedID(projectID, username, "admin")),
					resource.TestCheckResourceAttr(resourceName, "username", username),
					resource.TestCheckResourceAttr(resourceName, "labels.#", "1"),
					resource.TestCheckResourceAttr(resourceName, "roles.#", "1"),
				),
			},
			{
				// Convergence: empty plan from then on; failure here means a perpetual
				// diff, which is a parity gap, not an accepted migration diff.
				Config:                   configTPF,
				ProtoV6ProviderFactories: acc.TestAccProviderV6Factories,
				PlanOnly:                 true,
				ExpectNonEmptyPlan:       false,
			},
		},
	})
}

func encodedID(projectID, username, authDatabaseName string) string {
	return conversion.EncodeStateID(map[string]string{
		"project_id":         projectID,
		"username":           username,
		"auth_database_name": authDatabaseName,
	})
}

func checkExists(resourceName string) resource.TestCheckFunc {
	return func(s *terraform.State) error {
		rs, ok := s.RootModule().Resources[resourceName]
		if !ok {
			return fmt.Errorf("not found: %s", resourceName)
		}
		ids := conversion.DecodeStateID(rs.Primary.ID)
		_, _, err := acc.ConnV2().DatabaseUsersAPI.GetDatabaseUser(context.Background(),
			ids["project_id"], ids["auth_database_name"], ids["username"]).Execute()
		return err
	}
}

func checkDestroy(s *terraform.State) error {
	for _, rs := range s.RootModule().Resources {
		if rs.Type != "mongodbatlas_database_user" {
			continue
		}
		ids := conversion.DecodeStateID(rs.Primary.ID)
		_, _, err := acc.ConnV2().DatabaseUsersAPI.GetDatabaseUser(context.Background(),
			ids["project_id"], ids["auth_database_name"], ids["username"]).Execute()
		if err == nil {
			return fmt.Errorf("database user (%s) still exists", rs.Primary.ID)
		}
	}
	return nil
}
